from pathlib import Path
import subprocess, json, hashlib
R=Path.cwd(); G='midnight-club-los-angeles'
def old(path):return subprocess.check_output(['git','show','1ffb261cf0d5a5c97a0dcb7a2567b143bd8f87a6:'+path])
def doc(path):return json.loads((R/path).read_text())
def digest(b):return hashlib.sha256(b).hexdigest()
srcpath='dealership/public/'+G+'/index.json'; o=json.loads(old(srcpath)); n=doc(srcpath); om={r['code']:r for r in o['cars']}; nm={r['code']:r for r in n['cars']}
assert set(om)==set(nm) and len(nm)==106
assert all(om[c]['native_package']==nm[c]['native_package'] and om[c]['name_source']==nm[c]['name_source'] and om[c]['display_name']==nm[c]['display_name'] for c in nm)
assert all(nm[c]['source_profile']=='mcla-xbox360-static-stock-v2' for c in nm)
rows=[]
for c,r in nm.items():
 s=(R/'dealership/public'/G/r['file']).read_bytes(); d=(R/'dealership/dealership/models'/('MCLA_'+c.upper()+'.glb')).read_bytes(); z=(R/'dealership/public'/G/r['native_package']['file']).read_bytes()
 assert digest(s)==r['sha256'] and d==s and digest(z)==r['native_package']['sha256']; assert om[c]['sha256']!=r['sha256']
 rows.append({'code':c,'before_sha256':om[c]['sha256'],'after_sha256':digest(s),'native_zip_sha256':digest(z),'source_equals_dealership':True})
catalog='dealership/dealership/catalog.json'; assert (R/catalog).read_bytes()==old(catalog)
for p, key in [('dealership/public/models.json','cars'),('dealership/public/dealership/cars.json',None),('dealership/dealership/origins.json','cars')]:
 a=json.loads(old(p)); b=doc(p); a=a[key] if key else a; b=b[key] if key else b
 def other(x):return x.get('game')!=G and not x.get('code','').startswith('MCLA_') and not x.get('id','').startswith(G+'/')
 assert [x for x in a if other(x)]==[x for x in b if other(x)],p
changed=subprocess.check_output(['git','diff','--name-only'],text=True).splitlines()
foreign=[p for p in changed if p.endswith('.glb') and G not in p and '/MCLA_' not in p]; assert not foreign,foreign
result={'schema':1,'models':106,'new_profile':'mcla-xbox360-static-stock-v2','triangles':sum(r['records'][0]['triangles'] for r in nm.values()),'source_index_sha256':digest((R/srcpath).read_bytes()),'dealership_catalog_sha256':digest((R/'dealership/public/dealership/cars.json').read_bytes()),'native_zip_metadata_and_bytes_preserved':True,'editable_catalog_bytes_preserved':True,'other_game_rows_preserved':True,'other_game_glbs_changed':foreign,'records':rows,'claim_limits':['Hash and metadata preservation is not a visual fidelity check.','Both published sets are exact copies for this upgrade; future dealership edits remain independent.']}
(R/'.scratch/mcla-assembly-fix/preservation-cleanup-final.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k!='records'}))

